create table public.exams(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,academic_year_id uuid not null references public.academic_years(id),name text not null,starts_on date,ends_on date,published boolean not null default false,created_at timestamptz not null default now());
create table public.exam_subjects(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,exam_id uuid not null references public.exams(id) on delete cascade,class_id uuid not null references public.classes(id),subject_id uuid not null references public.subjects(id),max_marks numeric(8,2) not null default 100,pass_marks numeric(8,2) not null default 35,exam_date date,unique(exam_id,class_id,subject_id));
create table public.exam_marks(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,exam_subject_id uuid not null references public.exam_subjects(id) on delete cascade,student_id uuid not null references public.students(id) on delete cascade,marks numeric(8,2),absent boolean not null default false,remarks text,entered_by uuid references auth.users(id),updated_at timestamptz not null default now(),unique(exam_subject_id,student_id));
alter table public.exams enable row level security;alter table public.exam_subjects enable row level security;alter table public.exam_marks enable row level security;
create policy "read exams" on public.exams for select using(public.is_school_member(school_id));create policy "manage exams" on public.exams for all using(public.can_manage_school(school_id)) with check(public.can_manage_school(school_id));
create policy "read exam subjects" on public.exam_subjects for select using(public.is_school_member(school_id));create policy "manage exam subjects" on public.exam_subjects for all using(public.can_manage_school(school_id)) with check(public.can_manage_school(school_id));
create policy "read marks" on public.exam_marks for select using(public.is_school_member(school_id));create policy "manage marks" on public.exam_marks for all using(public.is_school_member(school_id)) with check(public.is_school_member(school_id));